4548  function price2num($amount,$rounding='',$alreadysqlnb=0)
4549  {
4550  	global $langs,$conf;
4551  
4552  	// Round PHP function does not allow number like '1,234.56' nor '1.234,56' nor '1 234,56'
4553  	// Numbers must be '1234.56'
4554  	// Decimal delimiter for PHP and database SQL requests must be '.'
4555  	$dec=','; $thousand=' ';
4556  	if ($langs->transnoentitiesnoconv("SeparatorDecimal") != "SeparatorDecimal")  $dec=$langs->transnoentitiesnoconv("SeparatorDecimal");
4557  	if ($langs->transnoentitiesnoconv("SeparatorThousand")!= "SeparatorThousand") $thousand=$langs->transnoentitiesnoconv("SeparatorThousand");
4558  	if ($thousand == 'None') $thousand='';
4559  	elseif ($thousand == 'Space') $thousand=' ';
4560  	//print "amount=".$amount." html=".$form." trunc=".$trunc." nbdecimal=".$nbdecimal." dec='".$dec."' thousand='".$thousand."'<br>";
4561  
4562  	// Convert value to universal number format (no thousand separator, '.' as decimal separator)
4563  	if ($alreadysqlnb != 1)	// If not a PHP number or unknown, we change format
4564  	{
4565  		//print 'PP'.$amount.' - '.$dec.' - '.$thousand.' - '.intval($amount).'<br>';
4566  
4567  		// Convert amount to format with dolibarr dec and thousand (this is because PHP convert a number
4568  		// to format defined by LC_NUMERIC after a calculation and we want source format to be like defined by Dolibarr setup.
4569  		if (is_numeric($amount))
4570  		{
4571  			// We put in temps value of decimal ("0.00001"). Works with 0 and 2.0E-5 and 9999.10
4572  			$temps=sprintf("%0.10F",$amount-intval($amount));	// temps=0.0000000000 or 0.0000200000 or 9999.1000000000
4573  			$temps=preg_replace('/([\.1-9])0+$/','\\1',$temps); // temps=0. or 0.00002 or 9999.1
4574  			$nbofdec=max(0,dol_strlen($temps)-2);	// -2 to remove "0."
4575  			$amount=number_format($amount,$nbofdec,$dec,$thousand);
4576  		}
4577  		//print "QQ".$amount.'<br>';
4578  
4579  		// Now make replace (the main goal of function)
4580  		if ($thousand != ',' && $thousand != '.') $amount=str_replace(',','.',$amount);	// To accept 2 notations for french users
4581  		$amount=str_replace(' ','',$amount);		// To avoid spaces
4582  		$amount=str_replace($thousand,'',$amount);	// Replace of thousand before replace of dec to avoid pb if thousand is .

